"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1107-06-01:0":{"b": ["Sûrkhâb b. Badr sterft (Shawwâl 500 / juni 1107); Abû Mansûr volgt hem op.", "a1931e53"], "d": ["Sûrkhâb b. Badr sterft (Shawwâl 500 / juni 1107); Abû Mansûr volgt hem op.", "a1931e53"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1109-07-31:0":{"b": ["Vizier Ahmad b. Nizâm al-Mulk wordt met een groot leger naar Alamut gestuurd; wegens de winter blijft het resultaat uit", "ba5263e5"], "d": ["De Seltsjoekse sultan Muhammad Tapar stuurde zijn vizier Ahmad b. Nizâm al-Mulk met een groot leger naar Alamut om Hasan-i Sabbâh uit te schakelen; de veldtocht bleef wegens de winter zonder resultaat. Het eigenlijke beleg zou in 1117 komen.", "2e2a9c88"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1113-06-18:0":{"b": ["In Aleppo worden samen met de plaatsvervangers van Hasan-i Sabbâh in Syrië veel Bâtinîs gedood", "c70cc81f"], "d": ["De Seltsjoekse sultan Muhammad Tapar vroeg Alp Arslan al-Akhras, malik van Aleppo, en Ra'îs al-Ahdâth Sa‘îd b. Badî‘ de Bâtinîs in de stad te doden; samen met de plaatsvervangers van Hasan-i Sabbâh in Syrië, zoals Abû Tâhir al-Sâ'igh, Ismâ‘îl al-Dâ‘î en de broer van Hakîm al-Munajjim, werden veel Bâtinîs gedood (507/1113).", "c7adbffa"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1117-01-01:0":{"b": ["De dynastie van de Annâziden komt ten einde (volgens Ibn al-Athîrs vermelding van 130 jaar)", "a533a1d6"], "d": ["De dynastie van de Annâziden komt ten einde (volgens Ibn al-Athîrs vermelding van 130 jaar)", "a533a1d6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1124-05-23:0":{"b": ["Hasan-i Sabbâh sterft in Alamut", "1dccca4f"], "d": ["Hasan-i Sabbâh sterft in Alamut", "1dccca4f"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1127-01-17:0":{"b": ["Sultan Sanjar belegert Alamut; het kasteel wordt niet ingenomen", "6b06eb0c"], "d": ["De Seltsjoekse sultan Sanjar belegerde in 521 (1127) Alamut, het centrum van de Nizârî-Ismâ‘îlieten; de inname van het kasteel bleek niet mogelijk.", "91215716"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1130-01-01:0":{"b": ["Sultan Mahmûd b. Muhammad Tapar belegert Alamut; het kasteel wordt niet ingenomen", "64d6b833"], "d": ["De Seltsjoekse sultan Mahmûd b. Muhammad Tapar belegerde in 524 (1130) Alamut; het kasteel viel niet.", "791399dc"]},
